# ---- response shape ----
def test_compat_response_shape(fresh_auth):
    a = _anon()
    from app.auth.repository import get_repository
    get_repository().grant_addon(a["user"]["id"], "compatibility")
    r = client.post("/api/v1/saju/compatibility", headers=_h(a["access_token"]), json=PAIR)
    body = r.json()["compatibility"]
    assert body["meta"]["schema_version"] == "1.0"
    assert body["meta"]["lang"] == "en"
    assert set(body["axes"].keys()) == {"elements", "day_master", "ten_gods", "sinsal"}
    assert "score" in body["overall"]
    assert "grade_label" in body["overall"]
    assert "disclaimer" in body
    assert "pair" in body
    assert body["pair"]["a"]["archetype"] == "THE_RADIATOR"
    assert body["pair"]["b"]["archetype"] == "THE_BLADE"


def test_compat_ko(fresh_auth):
    a = _anon()
    from app.auth.repository import get_repository
    get_repository().grant_addon(a["user"]["id"], "compatibility")
    payload = {**PAIR, "lang": "ko"}
    r = client.post("/api/v1/saju/compatibility", headers=_h(a["access_token"]), json=payload)
    assert r.status_code == 200
    body = r.json()["compatibility"]
    assert body["meta"]["lang"] == "ko"
    for axis in body["axes"].values():
        assert any("\uac00" <= ch <= "\ud7a3" for ch in axis["headline"])
    # overall.headline 도 한국어 (smoke 실패 재발 방지)
    assert any("\uac00" <= ch <= "\ud7a3" for ch in body["overall"]["headline"]), \
        f"overall.headline not Korean: {body['overall']['headline']!r}"


