def test_compat_no_ai_strings(fresh_auth):
    import json as _json
    a = _anon()
    from app.auth.repository import get_repository
    get_repository().grant_addon(a["user"]["id"], "compatibility")
    r = client.post("/api/v1/saju/compatibility", headers=_h(a["access_token"]), json=PAIR)
    blob = _json.dumps(r.json()).lower()
    for banned in ("gemini", "openai", "gpt-", "llm"):
        assert banned not in blob
